def P(id, name, qa, note, user="", defect="—", b1440=True, b390=True, deck=True, spec=None, dev="—"):
    d = {"id": id, "name": name, "qa": qa, "note": note, "user": user, "defect": defect, "dev": dev,
         "deck": f"deck/{id}.jpg" if deck else None,
         "b1440": (b1440 if isinstance(b1440, str) else f"v3/{id}-1440.jpg") if b1440 else None,
         "b390": (b390 if isinstance(b390, str) else f"v3/{id}-390.jpg") if b390 else None}
    if spec: d["spec"] = spec; d["deck_empty"] = "Spec only (no crop)"
    return d
